// Generates electron/build/seed-define.nsh from the repo (dev-boundary) seed
// at electron/default-config.json. The generated file contains the real key
// and is GITIGNORED — it must never be committed. Run via `npm run
// seed-define` (also wired as `prebuild` / `predist`).
//
// LIFECYCLE (documented per security review):
//   - CREATED: by `npm run seed-define`. Wired as `predist` so `npm run dist`
//     always regenerates it fresh (output is deterministic; a stale or
//     previously half-written copy is simply overwritten).
//   - REGENERATED UNCONDITIONALLY: registered as electron-builder
//     `build.beforePack` in electron/package.json, so EVERY electron-builder
//     invocation — npm-driven or a direct `electron-builder --win/--dir`
//     bypassing the npm pre-hooks — deterministically overwrites
//     build/seed-define.nsh from the canonical seed BEFORE the NSIS target is
//     compiled. A stale (but schema-valid) file left over from an earlier
//     failed build can therefore never be packaged: freshness no longer
//     depends on the `!ifndef` presence guard in build/installer.nsh.
//     app-builder-lib resolves the string via resolveFunction, dynamically
//     imports the .mjs and calls the named `beforePack` export
//     (util/resolve.js:30-52, platformPackager.js:153-163); a thrown error
//     fails the build.
//   - DELETED: after all artifacts are written by the electron-builder
//     `afterAllArtifactBuild` hook (scripts/cleanup-seed-define.mjs,
//     registered as build.afterAllArtifactBuild in electron/package.json), so
//     no key-bearing copy survives a completed build in the worktree.
//   - If a build dies after generation, the file still carries the current
//     key and the NEXT build of any kind regenerates it via beforePack (or
//     the npm pre-hooks), before it is used.
//
// Output (never printed, never logged):
//   !define PCU_SEED_KEY "<key>"
//   !define PCU_SEED_KEY_VERSION <int>
//   !define PCU_SEED_KEY_SCHEMA <int>
//
// The key is read from the active provider section (falls back to the first
// non-empty legacy plaintext field). Refuses to generate an empty define —
// the installer must never embed a blank seed silently.

'use strict';

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ELECTRON_DIR = path.resolve(HERE, '..');
const SEED_PATH = path.join(ELECTRON_DIR, 'default-config.json');
const OUT_PATH = path.join(ELECTRON_DIR, 'build', 'seed-define.nsh');

function fail(message) {
  throw new Error(`[seed-define] ${message}`);
}

function escapeNsis(value) {
  // NSIS string literals: escape double quotes and $ with the NSIS escape
  // character ($$). Backslashes are literal in NSIS strings.
  return value.replace(/\$/g, '$$$$').replace(/"/g, '$\\"');
}

// Generates build/seed-define.nsh from the canonical seed. Paths are resolved
// from this module's own location (import.meta.url), never process.cwd(), so
// the generation works no matter which cwd electron-builder or npm invokes it
// with. Throws on failure (callers: the beforePack hook — an error fails the
// build; the CLI wrapper below — exits nonzero).
export function generateSeedDefine() {
  let seed;
  try {
    seed = JSON.parse(fs.readFileSync(SEED_PATH, 'utf8'));
  } catch (err) {
    fail(`cannot read seed at ${SEED_PATH}: ${err.message}`);
  }

  const SECTIONS = ['openai', 'anthropic', 'openai_compat'];
  let key = null;
  for (const section of SECTIONS) {
    const sub = seed[section];
    if (sub && typeof sub === 'object' && typeof sub.api_key === 'string' && sub.api_key.trim() !== '') {
      key = sub.api_key.trim();
      break;
    }
  }
  if (!key && typeof seed.apiKey === 'string' && seed.apiKey.trim() !== '') {
    key = seed.apiKey.trim();
  }
  if (!key) {
    fail('seed contains no plaintext key; refusing to generate an empty seed define');
  }

  let keyVersion = 1;
  if (typeof seed.keyVersion === 'number' && Number.isFinite(seed.keyVersion)) {
    keyVersion = seed.keyVersion;
  }

  // Bump when the define set changes; installer.nsh !errors on copies
  // generated before the sentinel existed.
  const SEED_SCHEMA_VERSION = 1;

  const body =
    `# GENERATED by electron/scripts/gen-seed-define.mjs - DO NOT COMMIT.\n` +
    `# Contains the bundled seed key; gitignored via electron/.gitignore.\n` +
    `# Schema ${SEED_SCHEMA_VERSION}: the PCU_SEED_KEY_SCHEMA define below is the\n` +
    `# staleness sentinel checked by build/installer.nsh.\n` +
    `!define PCU_SEED_KEY "${escapeNsis(key)}"\n` +
    `!define PCU_SEED_KEY_VERSION ${keyVersion}\n` +
    `!define PCU_SEED_KEY_SCHEMA ${SEED_SCHEMA_VERSION}\n`;

  try {
    fs.mkdirSync(path.dirname(OUT_PATH), { recursive: true });
    fs.writeFileSync(OUT_PATH, body, 'utf8');
  } catch (err) {
    fail(`cannot write ${OUT_PATH}: ${err.message}`);
  }

  // Never echo the key: report only its length and version.
  console.log(`[seed-define] wrote ${OUT_PATH} (key length ${key.length}, keyVersion ${keyVersion})`);
}

// electron-builder beforePack hook (build.beforePack in electron/package.json).
// Fires on every electron-builder path before any target is compiled, so the
// NSIS seed define is always regenerated fresh from the canonical seed. The
// hook's return value is unused by app-builder-lib; a throw fails the build.
export function beforePack() {
  generateSeedDefine();
}

export default beforePack;

const SELF_PATH = fileURLToPath(import.meta.url);
const invokedDirectly =
  process.argv[1] != null &&
  path.resolve(process.argv[1]).replace(/\\/g, '/').toLowerCase() === SELF_PATH.replace(/\\/g, '/').toLowerCase();
if (invokedDirectly) {
  try {
    generateSeedDefine();
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }
};
